class Solution {
    public String digitSum(String s,int k){
        while(s.length()>k){
            StringBuilder next=new StringBuilder();
            for(int start=0;start<s.length();start+=k){
                int sum=0;
                for(int i=start;i<Math.min(start+k,s.length());i++)sum+=s.charAt(i)-'0';
                next.append(sum);
            }
            s=next.toString();
        }
        return s;
    }
}

code.kotlin:
class Solution {
    fun digitSum(sValue:String,k:Int):String{
        var s=sValue;
        while(s.length>k){
            val next=StringBuilder();
            for(start in s.indices step k){
                var sum=0;
                for(i in start until minOf(start+k,s.length))sum+=s[i]-'0';
                next.append(sum)
            };
            s=next.toString()
        };
        return s
    }
}

